INSERT INTO crops (name, hindi_name, category, season, soil, irrigation, fertilizer, diseases, yield_info, image_url, temperature_range, water_requirement, sowing_months, harvesting_months) VALUES ('Tomato - Abhinav (Syngenta)', 'टमाटर (Abhinav (Syngenta))', 'Vegetables', 'Round-the-year (Kharif, Rabi, Summer)', 'Well-drained sandy loam to fertile clay loam rich in organic matter (pH 6.0 - 7.0)', 'Drip irrigation recommended (1-2 hours daily or surface irrigation every 5-7 days)', 'Basal: 50kg DAP + 40kg MOP + 30kg Urea. Fertigation: 19:19:19 & 0:52:34 with micronutrient spray.', 'Tomato Leaf Curl Virus (ToLCV), Early & Late Blight, Bacterial Wilt, Fruit Borer (Helicoverpa)', '200-300 quintals/acre [Certified: Abhinav (Syngenta)]', 'https://images.unsplash.com/photo-1592924357228-91a4daadcfea?auto=format&fit=crop&w=360&q=75', '18°C - 28°C', '600 - 800 mm', 'July / October / February', 'October / February / May');
