INSERT INTO crops (name, hindi_name, category, season, soil, irrigation, fertilizer, diseases, yield_info, image_url, temperature_range, water_requirement, sowing_months, harvesting_months) VALUES ('Onion - Nashik Red', 'प्याज़ (Nashik Red)', 'Vegetables', 'Kharif (June), Late Kharif (August), Rabi (October - November)', 'Rich, well-drained loamy soil with high organic content (pH 6.0 - 7.5)', '10-15 light irrigations (Critical: bulb initiation and enlargement; stop 15 days before harvest)', 'Basal: 45kg DAP + 40kg MOP + 35kg Urea + 20kg Sulphur. Top dress: 40kg Urea at 30 & 45 DAT.', 'Purple Blotch (Alternaria porri), Stemphylium Blight, Thrips (Thrips tabaci), Basal Rot', '100-150 quintals/acre [Certified: Nashik Red]', 'https://images.unsplash.com/photo-1618512496248-a07fe83aa8cb?auto=format&fit=crop&w=360&q=75', '15°C - 30°C', '500 - 700 mm', 'June / October', 'October / April');
