INSERT INTO crops (name, hindi_name, category, season, soil, irrigation, fertilizer, diseases, yield_info, image_url, temperature_range, water_requirement, sowing_months, harvesting_months) VALUES ('Mango - Alphonso (Ratnagiri Hapus)', 'आम (Alphonso (Ratnagiri Hapus))', 'Fruits', 'Planting: July - August (Monsoon)', 'Deep, fertile alluvial or rich loamy soil up to 2m depth with good drainage (pH 5.5 - 7.5)', 'Young plants: every 3-5 days; bearing trees: irrigate at fruit setting until maturity, withhold 2 months before flowering', 'Per mature tree (10+ yrs): 1kg Urea + 1.5kg SSP (or 750g DAP) + 1kg MOP + 50kg FYM in July; Boron foliar spray at bloom.', 'Powdery Mildew, Anthracnose, Mango Malformation, Bacterial Canker, Fruit Fly (Bactrocera dorsalis)', '60-100 quintals/acre mature orchard [Certified: Alphonso (Ratnagiri Hapus)]', 'https://images.unsplash.com/photo-1553279768-865429fa0078?auto=format&fit=crop&w=360&q=75', '24°C - 35°C', '750 - 1500 mm', 'July - August', 'April - July');
