INSERT INTO crops (name, hindi_name, category, season, soil, irrigation, fertilizer, diseases, yield_info, image_url, temperature_range, water_requirement, sowing_months, harvesting_months) VALUES ('Banana - Grand Naine (G-9 Tissue Culture)', 'केला (Grand Naine (G-9 Tissue Culture))', 'Fruits', 'June - July or September - October', 'Deep, rich fertile loamy soil with high moisture holding capacity and good aeration (pH 6.0 - 7.5)', 'High water demand; drip irrigation: 15-20 liters/plant/day; surface: every 5-7 days in summer', 'Per plant: 200g Urea + 250g SSP + 300g MOP applied in 4 splits during 2nd, 3rd, 4th, and 5th month of planting.', 'Panama Wilt (Fusarium oxysporum), Sigatoka Leaf Spot, Banana Bunchy Top Virus (BBTV), Rhizome Weevil', '250-350 quintals/acre [Certified: Grand Naine (G-9 Tissue Culture)]', 'https://images.unsplash.com/photo-1571771894821-ce9b6c11b08e?auto=format&fit=crop&w=360&q=75', '20°C - 35°C', '1200 - 2000 mm', 'June - July', '11-12 months after planting');
