INSERT INTO crops (name, hindi_name, category, season, soil, irrigation, fertilizer, diseases, yield_info, image_url, temperature_range, water_requirement, sowing_months, harvesting_months) VALUES ('Apple - Red Delicious (Shimla / Kinnaur)', 'सेब (Red Delicious (Shimla / Kinnaur))', 'Fruits', 'Winter planting (December - February, Dormant period)', 'Deep, fertile sandy loam with good organic content and cold drainage on hill slopes (pH 5.5 - 6.8)', '6-8 irrigations during spring and summer (Critical: fruit set, fruit development; drip irrigation highly beneficial)', 'Per mature tree: 700g Nitrogen + 350g P2O5 + 700g K2O + 40kg well-rotted FYM in December.', 'Apple Scab (Venturia inaequalis), Powdery Mildew, Alternaria Leaf Blotches, Woolly Apple Aphid, San Jose Scale', '80-140 quintals/acre high density [Certified: Red Delicious (Shimla / Kinnaur)]', 'https://images.unsplash.com/photo-1560806887-1e4cd0b6cbd6?auto=format&fit=crop&w=360&q=75', '7°C - 24°C (Needs 800-1200 chilling hours <7°C)', '1000 - 1250 mm', 'December - February', 'July - October');
