INSERT INTO crops (name, hindi_name, category, season, soil, irrigation, fertilizer, diseases, yield_info, image_url, temperature_range, water_requirement, sowing_months, harvesting_months) VALUES ('Pomegranate - Bhagwa (Sindhuri / Shendari GI)', 'अनार (Bhagwa (Sindhuri / Shendari GI))', 'Fruits', 'Planting: July - August or February - March', 'Well-drained light loamy to medium black soils (highly drought and moderate salinity tolerant, pH 6.5 - 8.0)', 'Drip irrigation: 10-25 liters/day/plant; Bahar treatment requires withholding water for 40-50 days before flower induction', 'Per mature tree: 600g Urea + 500g SSP + 400g MOP in 3 splits + Zinc & Boron foliar spray at fruit set.', 'Bacterial Blight / Oily Spot (Xanthomonas axonopodis pv. punicae), Anthracnose, Fruit Borer (Deudorix isocrates)', '40-70 quintals/acre [Certified: Bhagwa (Sindhuri / Shendari GI)]', 'https://images.unsplash.com/photo-1615485500704-8e990f9900f7?auto=format&fit=crop&w=360&q=75', '25°C - 38°C', '500 - 750 mm', 'July - August', '5-6 months after flowering');
