INSERT INTO crops (name, hindi_name, category, season, soil, irrigation, fertilizer, diseases, yield_info, image_url, temperature_range, water_requirement, sowing_months, harvesting_months) VALUES ('Spices & Condiments (Cumin / Jeera) - GC-4 (Gujarat Cumin 4)', 'ज़ीरा (GC-4 (Gujarat Cumin 4))', 'Spices', 'Rabi (November)', 'Well-drained sandy loam to fertile loamy soils rich in organic matter (pH 6.8 - 8.0)', '3-4 light irrigations (Crucial: First light immediately after sowing, 2nd at 7-10 days, 3rd at 35 days, 4th at flowering)', 'Basal: 30kg DAP + 15kg MOP + 20kg Urea + 10kg Sulphur. Top dress: 20kg Urea at 30 DAS.', 'Fusarium Wilt, Blight (Alternaria burnsii), Powdery Mildew, Aphids', '4-7 quintals/acre [Certified: GC-4 (Gujarat Cumin 4)]', 'https://images.unsplash.com/photo-1596040033229-a9821ebd058d?auto=format&fit=crop&w=360&q=75', '12°C - 26°C', '250 - 350 mm', 'November', 'February - March');
