INSERT INTO fertilizers (name, hindi_name, category, type, composition, usage_instruction, precautions, suitable_crops, image_url, price_per_bag, subsidized, standard_pack_size) VALUES ('GSFC Sardar - Zinc Sulphate 33% Monohydrate', 'जीएसएफसी सरदार - जिंक सल्फेट 33%', 'Micronutrients', 'GSFC Sardar Essential Zinc & Sulphur Micronutrient', '33.0% Zinc (Zn) + 15.0% Sulphur (S)', 'Soil application 5-7.5 kg/acre or foliar spray 0.5% with lime. Prevents Khaira disease in paddy.', 'Never mix directly with DAP or SSP in water tank.', 'Paddy, Wheat, Maize, Citrus, Cotton, Sugarcane', 'https://images.unsplash.com/photo-1585314062340-f1a5a7c9328d?auto=format&fit=crop&w=360&q=75', '₹436.50', false, '5 kg Pack');
INSERT INTO fertilizers (name, hindi_name, category, type, composition, usage_instruction, precautions, suitable_crops, image_url, price_per_bag, subsidized, standard_pack_size) VALUES ('GSFC Sardar - Chelated Zinc EDTA 12%', 'जीएसएफसी सरदार - चिलेटेड जिंक 12%', 'Micronutrients', 'GSFC Sardar 100% Water Soluble Chelate', '12.0% Zinc in EDTA chelated form', 'Foliar spray @ 1g/L water during active growth; rapid absorption through leaves.', 'Compatible with most common agricultural sprays.', 'Paddy, Citrus, Cotton, Apple, Tomato, Vegetables', 'https://images.unsplash.com/photo-1615485290382-441e4d049cb5?auto=format&fit=crop&w=360&q=75', '₹368.60', false, '1 kg Pouch');
INSERT INTO fertilizers (name, hindi_name, category, type, composition, usage_instruction, precautions, suitable_crops, image_url, price_per_bag, subsidized, standard_pack_size) VALUES ('GSFC Sardar - Borax 10.5% / Disodium Octaborate 20%', 'जीएसएफसी सरदार - बोरेक्स / बोरॉन', 'Micronutrients', 'GSFC Sardar Essential Boron Micronutrient', '10.5% Boron for soil / 20.0% Solubor for foliar spray', 'Soil: 2-4 kg/acre. Foliar: 1g/L water at flower initiation to prevent flower dropping.', 'Avoid overdosing which causes boron toxicity.', 'Tomato, Pomegranate, Mustard, Cauliflower, Apple', 'https://images.unsplash.com/photo-1615485290382-441e4d049cb5?auto=format&fit=crop&w=360&q=75', '₹232.80', false, '1 kg Pack');
INSERT INTO fertilizers (name, hindi_name, category, type, composition, usage_instruction, precautions, suitable_crops, image_url, price_per_bag, subsidized, standard_pack_size) VALUES ('GSFC Sardar - Agricultural Gypsum (CaSO4.2H2O)', 'जीएसएफसी सरदार - कृषि जिप्सम', 'Soil Amendments', 'GSFC Sardar Calcium & Sulphur Soil Conditioner', '70-80% Calcium Sulphate (23% Ca + 18% S)', 'Reclamation of alkali soils: 200-500 kg/acre. Groundnut pegging: 100 kg/acre.', 'Broadcast uniformly and incorporate into top 10 cm soil.', 'Groundnut, Mustard, Sodic soils, Potato, Sugarcane', 'https://images.unsplash.com/photo-1567401893414-76b7b1e5a7a5?auto=format&fit=crop&w=360&q=75', '₹350.00', true, '50 kg Bag');
INSERT INTO fertilizers (name, hindi_name, category, type, composition, usage_instruction, precautions, suitable_crops, image_url, price_per_bag, subsidized, standard_pack_size) VALUES ('GSFC Sardar - Calcium Nitrate (15.5% N + 18.8% Ca)', 'जीएसएफसी सरदार - कैल्शियम नाइट्रेट', 'Secondary Nutrients', 'GSFC Sardar Water Soluble Plant Nutrient', '15.5% Nitrate Nitrogen + 18.8% Water Soluble Calcium', 'Drip fertigation @ 3-5 kg/acre or foliar spray @ 5g/L. Prevents blossom end rot in tomato.', 'Do not mix with sulphate or phosphate fertilizers in concentrated stock solution.', 'Tomato, Apple, Pomegranate, Potato, Capsicum', 'https://images.unsplash.com/photo-1567401893414-76b7b1e5a7a5?auto=format&fit=crop&w=360&q=75', '₹1,794.50', false, '25 kg Bag');
INSERT INTO fertilizers (name, hindi_name, category, type, composition, usage_instruction, precautions, suitable_crops, image_url, price_per_bag, subsidized, standard_pack_size) VALUES ('GSFC Sardar - Magnesium Sulphate (Epsom Salt 9.6% Mg + 12% S)', 'जीएसएफसी सरदार - मैग्नीशियम सल्फेट', 'Secondary Nutrients', 'GSFC Sardar Chlorophyll Booster', '9.6% Magnesium + 12.0% Sulphur', 'Soil application: 15-25 kg/acre. Foliar: 5g/L. Restores lush green color and photosynthesis.', 'Fast acting; highly water soluble.', 'Cotton, Sugarcane, Citrus, Banana, Tomato, Tea', 'https://images.unsplash.com/photo-1567401893414-76b7b1e5a7a5?auto=format&fit=crop&w=360&q=75', '₹727.50', false, '25 kg Bag');
INSERT INTO fertilizers (name, hindi_name, category, type, composition, usage_instruction, precautions, suitable_crops, image_url, price_per_bag, subsidized, standard_pack_size) VALUES ('GSFC Sardar - 100% Water Soluble NPK 19:19:19', 'जीएसएफसी सरदार - घुलनशील 19:19:19', 'Water Soluble & Foliar', 'GSFC Sardar Foliar & Fertigation Grade', '19% N, 19% P2O5, 19% K2O with balanced trace elements', 'Foliar spray @ 5g/L or fertigation @ 3-5 kg/acre during vegetative stage.', 'Completely soluble in water leaving no residue in drip nozzles.', 'Vegetables, Floriculture, Cotton, Fruits, Wheat', 'https://images.unsplash.com/photo-1592924357228-91a4daadcfea?auto=format&fit=crop&w=360&q=75', '₹174.60', false, '1 kg Pack');
INSERT INTO fertilizers (name, hindi_name, category, type, composition, usage_instruction, precautions, suitable_crops, image_url, price_per_bag, subsidized, standard_pack_size) VALUES ('GSFC Sardar - Mono Potassium Phosphate 0:52:34 (MKP)', 'जीएसएफसी सरदार - एमकेपी 0:52:34', 'Water Soluble & Foliar', 'GSFC Sardar Pre-flowering & Fruit Set Booster', '52.0% Available Phosphate + 34.0% Soluble Potash', 'Foliar spray @ 5g/L or drip @ 3kg/acre during bud initiation and grain filling.', 'Increases fruit size, sweetness (Brix), and disease resistance.', 'Grapes, Pomegranate, Tomato, Chilli, Wheat, Apple', 'https://images.unsplash.com/photo-1592924357228-91a4daadcfea?auto=format&fit=crop&w=360&q=75', '₹213.40', false, '1 kg Pack');
INSERT INTO fertilizers (name, hindi_name, category, type, composition, usage_instruction, precautions, suitable_crops, image_url, price_per_bag, subsidized, standard_pack_size) VALUES ('GSFC Sardar - Potassium Nitrate 13:0:45', 'जीएसएफसी सरदार - पोटेशियम नाइट्रेट 13:0:45', 'Water Soluble & Foliar', 'GSFC Sardar Fruit Maturity & Color Booster', '13.0% Nitrate Nitrogen + 45.0% Water Soluble Potash', 'Foliar spray @ 5-10g/L during fruit enlargement and ripening.', 'Improves fruit uniform ripening, shine, shelf life, and weight.', 'Pomegranate, Banana, Mango, Tomato, Potato, Onion', 'https://images.unsplash.com/photo-1615811361523-6bd03d7748e7?auto=format&fit=crop&w=360&q=75', '₹203.70', false, '1 kg Pack');
INSERT INTO fertilizers (name, hindi_name, category, type, composition, usage_instruction, precautions, suitable_crops, image_url, price_per_bag, subsidized, standard_pack_size) VALUES ('GSFC Sardar - Biofertilizer Consortia (NPK Liquid)', 'जीएसएफसी सरदार - तरल बायो एनपीके', 'Organic & Biofertilizers', 'GSFC Sardar Microbial Liquid Inoculant', 'Live strains of Azotobacter (Nitrogen fixing), Bacillus (PSB), and Frateuria (KMB) (1x10^8 CFU/ml)', 'Seed treatment: 10ml/kg; Soil drench or drip: 1 Liter/acre in 200L water.', 'Store in cool place out of direct sunlight. Do not mix with chemical bactericides.', 'All crops, organic farming, cereals, pulses, vegetables', 'https://images.unsplash.com/photo-1589923188900-85dae523342b?auto=format&fit=crop&w=360&q=75', '₹271.60', false, '1 Liter Bottle');
INSERT INTO fertilizers (name, hindi_name, category, type, composition, usage_instruction, precautions, suitable_crops, image_url, price_per_bag, subsidized, standard_pack_size) VALUES ('GSFC Sardar - Enriched Vermicompost (Organic Carbon 18%)', 'जीएसएफसी सरदार - वर्मीकम्पोस्ट (केंचुआ खाद)', 'Organic & Biofertilizers', 'GSFC Sardar 100% Organic Soil Enrichment', 'Organic Carbon 18-20%, Total N 1.8%, P 1.2%, K 1.5%, beneficial enzymes & worm castings', '1-2 tons per acre before last ploughing or 3-5 kg per fruit tree basin.', 'Eco-friendly; enhances soil water retention and beneficial soil microbiology.', 'All crops, organic farming, horticulture, greenhouse', 'https://images.unsplash.com/photo-1589923188900-85dae523342b?auto=format&fit=crop&w=360&q=75', '₹310.40', false, '40 kg Bag');
INSERT INTO fertilizers (name, hindi_name, category, type, composition, usage_instruction, precautions, suitable_crops, image_url, price_per_bag, subsidized, standard_pack_size) VALUES ('GSFC Sardar - Pure Cold-Pressed Neem Cake Powder', 'जीएसएफसी सरदार - नीम की खली (नीम केक)', 'Organic & Biofertilizers', 'GSFC Sardar Organic Manure & Nematicide', 'Azadirachtin content >1000 ppm, N 4.0%, P 1.0%, K 1.5%', 'Apply 100-150 kg/acre at soil preparation. Inhibits nitrification and controls soil nematodes.', 'Safe for earthworms and soil flora.', 'Vegetables, Potato, Banana, Spices, Cotton, Pomegranate', 'https://images.unsplash.com/photo-1589923188900-85dae523342b?auto=format&fit=crop&w=360&q=75', '₹824.50', false, '50 kg Bag');
INSERT INTO fertilizers (name, hindi_name, category, type, composition, usage_instruction, precautions, suitable_crops, image_url, price_per_bag, subsidized, standard_pack_size) VALUES ('GSFC Sardar - Liquid Humic Acid 12% + Fulvic Acid', 'जीएसएफसी सरदार - ह्यूमिक एसिड लिक्विड', 'Organic & Biofertilizers', 'GSFC Sardar Root Stimulant & Soil Conditioner', '12% Potassium Humate + Fulvic Acid + Amino Acids', 'Drenching or drip @ 1-2 Liters/acre; seed treatment @ 5ml/kg. Stimulates white feeder root growth.', 'Shake well before use. Compatible with NPK and micronutrients.', 'All crops during seedling and vegetative stages', 'https://images.unsplash.com/photo-1589923188900-85dae523342b?auto=format&fit=crop&w=360&q=75', '₹329.80', false, '1 Liter Bottle');
INSERT INTO fertilizers (name, hindi_name, category, type, composition, usage_instruction, precautions, suitable_crops, image_url, price_per_bag, subsidized, standard_pack_size) VALUES ('Tata Paras - Neem Coated Urea (46% N)', 'टाटा पारस - नीम कोटेड यूरिया', 'Nitrogenous', 'Tata Paras Nitrogen Fertilizer', '46.0% Total Nitrogen (Amide form) with 0.05% neem oil coating', 'Basal application at sowing + 2-3 split top dressings during vegetative growth.', 'Avoid overuse which causes lodging and pest susceptibility. Apply only on moist soil.', 'Wheat, Rice, Maize, Sugarcane, Cotton', 'https://images.unsplash.com/photo-1585314062340-f1a5a7c9328d?auto=format&fit=crop&w=360&q=75', '₹266.50', true, '45 kg Bag');
INSERT INTO fertilizers (name, hindi_name, category, type, composition, usage_instruction, precautions, suitable_crops, image_url, price_per_bag, subsidized, standard_pack_size) VALUES ('Tata Paras - DAP (Di-Ammonium Phosphate 18:46:0)', 'टाटा पारस - डीएपी', 'Phosphatic', 'Tata Paras Phosphorus & Nitrogen Complex', '18.0% Ammoniacal Nitrogen + 46.0% Available Phosphate (P2O5)', 'Basal dose at sowing near root zone for vigorous root growth.', 'Store in dry place. Do not mix with quicklime or calcium nitrate.', 'All crops: Wheat, Paddy, Potato, Mustard, Pulses', 'https://images.unsplash.com/photo-1628352081506-83c43123ed6d?auto=format&fit=crop&w=360&q=75', '₹1,350.00', true, '50 kg Bag');
INSERT INTO fertilizers (name, hindi_name, category, type, composition, usage_instruction, precautions, suitable_crops, image_url, price_per_bag, subsidized, standard_pack_size) VALUES ('Tata Paras - MOP (Muriate of Potash 0:0:60)', 'टाटा पारस - एमओपी (पोटाश)', 'Potassic', 'Tata Paras Potassium Fertilizer', '60.0% Water Soluble Potash (K2O as KCl)', 'Basal or split application for heavy feeding crops; boosts grain weight and drought resistance.', 'Avoid for chloride-sensitive crops like tobacco, grapes, potato starch.', 'Paddy, Sugarcane, Wheat, Maize, Cotton, Banana', 'https://images.unsplash.com/photo-1615811361523-6bd03d7748e7?auto=format&fit=crop&w=360&q=75', '₹1,650.00', true, '50 kg Bag');
