INSERT INTO fertilizers (name, hindi_name, category, type, composition, usage_instruction, precautions, suitable_crops, image_url, price_per_bag, subsidized, standard_pack_size) VALUES ('Zuari Jai Kisaan - NPK 12:32:16 Complex', 'ज़ुआरी जय किसान - एनपीके 12:32:16', 'Complex NPK', 'Zuari Jai Kisaan High Phosphate Complex', '12.0% N, 32.0% P2O5, 16.0% K2O', 'High phosphorus booster for root proliferation and early plant establishment.', 'Incorporate 3-5 cm below seed depth.', 'Wheat, Mustard, Soybean, Paddy, Groundnut', 'https://images.unsplash.com/photo-1592924357228-91a4daadcfea?auto=format&fit=crop&w=360&q=75', '₹1,470.00', true, '50 kg Bag');
INSERT INTO fertilizers (name, hindi_name, category, type, composition, usage_instruction, precautions, suitable_crops, image_url, price_per_bag, subsidized, standard_pack_size) VALUES ('Zuari Jai Kisaan - NPK 20:20:0:13 Ammonium Phosphate Sulphate', 'ज़ुआरी जय किसान - एनपीके 20:20:0:13 (सल्फर युक्त)', 'Complex NPK', 'Zuari Jai Kisaan Nitrogen, Phosphate & Sulphur Complex', '20.0% N, 20.0% P2O5, 13.0% Sulphur', 'Excellent for oilseeds and pulses where sulphur is critical for oil and protein synthesis.', 'Store away from direct moisture.', 'Mustard, Soybean, Groundnut, Sunflower, Pulses', 'https://images.unsplash.com/photo-1592924357228-91a4daadcfea?auto=format&fit=crop&w=360&q=75', '₹1,320.00', true, '50 kg Bag');
INSERT INTO fertilizers (name, hindi_name, category, type, composition, usage_instruction, precautions, suitable_crops, image_url, price_per_bag, subsidized, standard_pack_size) VALUES ('Zuari Jai Kisaan - Single Super Phosphate (SSP 16% P2O5 + 11% S)', 'ज़ुआरी जय किसान - एसएसपी (सुपर फॉस्फेट)', 'Phosphatic', 'Zuari Jai Kisaan Phosphorus, Calcium & Sulphur Fertilizer', '16.0% Water Soluble Phosphate + 11.0% Sulphur + 19.0% Calcium', 'Basal application at field preparation or sowing; soil conditioner for sodic soils.', 'Can be mixed with Urea at time of application; do not store mixed.', 'Groundnut, Mustard, Soybean, Pulses, Potato', 'https://images.unsplash.com/photo-1500937386664-56d1dfef3854?auto=format&fit=crop&w=360&q=75', '₹520.00', true, '50 kg Bag');
INSERT INTO fertilizers (name, hindi_name, category, type, composition, usage_instruction, precautions, suitable_crops, image_url, price_per_bag, subsidized, standard_pack_size) VALUES ('Zuari Jai Kisaan - Zinc Sulphate 33% Monohydrate', 'ज़ुआरी जय किसान - जिंक सल्फेट 33%', 'Micronutrients', 'Zuari Jai Kisaan Essential Zinc & Sulphur Micronutrient', '33.0% Zinc (Zn) + 15.0% Sulphur (S)', 'Soil application 5-7.5 kg/acre or foliar spray 0.5% with lime. Prevents Khaira disease in paddy.', 'Never mix directly with DAP or SSP in water tank.', 'Paddy, Wheat, Maize, Citrus, Cotton, Sugarcane', 'https://images.unsplash.com/photo-1585314062340-f1a5a7c9328d?auto=format&fit=crop&w=360&q=75', '₹463.50', false, '5 kg Pack');
