INSERT INTO fertilizers (name, hindi_name, category, type, composition, usage_instruction, precautions, suitable_crops, image_url, price_per_bag, subsidized, standard_pack_size) VALUES ('IPL Potash - NPK 10:26:26 Complex', 'आईपीएल - एनपीके 10:26:26', 'Complex NPK', 'IPL Potash Complete Balanced Fertilizer', '10.0% N, 26.0% P2O5, 26.0% K2O', 'Ideal basal fertilizer for heavy feeding crops and root/tuber development.', 'Uniform granule distribution ensures balanced nutrition.', 'Cotton, Sugarcane, Potato, Pulses, Oilseeds', 'https://images.unsplash.com/photo-1592924357228-91a4daadcfea?auto=format&fit=crop&w=360&q=75', '₹1,470.00', true, '50 kg Bag');
INSERT INTO fertilizers (name, hindi_name, category, type, composition, usage_instruction, precautions, suitable_crops, image_url, price_per_bag, subsidized, standard_pack_size) VALUES ('IPL Potash - NPK 12:32:16 Complex', 'आईपीएल - एनपीके 12:32:16', 'Complex NPK', 'IPL Potash High Phosphate Complex', '12.0% N, 32.0% P2O5, 16.0% K2O', 'High phosphorus booster for root proliferation and early plant establishment.', 'Incorporate 3-5 cm below seed depth.', 'Wheat, Mustard, Soybean, Paddy, Groundnut', 'https://images.unsplash.com/photo-1592924357228-91a4daadcfea?auto=format&fit=crop&w=360&q=75', '₹1,470.00', true, '50 kg Bag');
INSERT INTO fertilizers (name, hindi_name, category, type, composition, usage_instruction, precautions, suitable_crops, image_url, price_per_bag, subsidized, standard_pack_size) VALUES ('IPL Potash - NPK 20:20:0:13 Ammonium Phosphate Sulphate', 'आईपीएल - एनपीके 20:20:0:13 (सल्फर युक्त)', 'Complex NPK', 'IPL Potash Nitrogen, Phosphate & Sulphur Complex', '20.0% N, 20.0% P2O5, 13.0% Sulphur', 'Excellent for oilseeds and pulses where sulphur is critical for oil and protein synthesis.', 'Store away from direct moisture.', 'Mustard, Soybean, Groundnut, Sunflower, Pulses', 'https://images.unsplash.com/photo-1592924357228-91a4daadcfea?auto=format&fit=crop&w=360&q=75', '₹1,320.00', true, '50 kg Bag');
INSERT INTO fertilizers (name, hindi_name, category, type, composition, usage_instruction, precautions, suitable_crops, image_url, price_per_bag, subsidized, standard_pack_size) VALUES ('IPL Potash - Single Super Phosphate (SSP 16% P2O5 + 11% S)', 'आईपीएल - एसएसपी (सुपर फॉस्फेट)', 'Phosphatic', 'IPL Potash Phosphorus, Calcium & Sulphur Fertilizer', '16.0% Water Soluble Phosphate + 11.0% Sulphur + 19.0% Calcium', 'Basal application at field preparation or sowing; soil conditioner for sodic soils.', 'Can be mixed with Urea at time of application; do not store mixed.', 'Groundnut, Mustard, Soybean, Pulses, Potato', 'https://images.unsplash.com/photo-1500937386664-56d1dfef3854?auto=format&fit=crop&w=360&q=75', '₹520.00', true, '50 kg Bag');
INSERT INTO fertilizers (name, hindi_name, category, type, composition, usage_instruction, precautions, suitable_crops, image_url, price_per_bag, subsidized, standard_pack_size) VALUES ('IPL Potash - Zinc Sulphate 33% Monohydrate', 'आईपीएल - जिंक सल्फेट 33%', 'Micronutrients', 'IPL Potash Essential Zinc & Sulphur Micronutrient', '33.0% Zinc (Zn) + 15.0% Sulphur (S)', 'Soil application 5-7.5 kg/acre or foliar spray 0.5% with lime. Prevents Khaira disease in paddy.', 'Never mix directly with DAP or SSP in water tank.', 'Paddy, Wheat, Maize, Citrus, Cotton, Sugarcane', 'https://images.unsplash.com/photo-1585314062340-f1a5a7c9328d?auto=format&fit=crop&w=360&q=75', '₹436.50', false, '5 kg Pack');
INSERT INTO fertilizers (name, hindi_name, category, type, composition, usage_instruction, precautions, suitable_crops, image_url, price_per_bag, subsidized, standard_pack_size) VALUES ('IPL Potash - Chelated Zinc EDTA 12%', 'आईपीएल - चिलेटेड जिंक 12%', 'Micronutrients', 'IPL Potash 100% Water Soluble Chelate', '12.0% Zinc in EDTA chelated form', 'Foliar spray @ 1g/L water during active growth; rapid absorption through leaves.', 'Compatible with most common agricultural sprays.', 'Paddy, Citrus, Cotton, Apple, Tomato, Vegetables', 'https://images.unsplash.com/photo-1615485290382-441e4d049cb5?auto=format&fit=crop&w=360&q=75', '₹368.60', false, '1 kg Pouch');
INSERT INTO fertilizers (name, hindi_name, category, type, composition, usage_instruction, precautions, suitable_crops, image_url, price_per_bag, subsidized, standard_pack_size) VALUES ('IPL Potash - Borax 10.5% / Disodium Octaborate 20%', 'आईपीएल - बोरेक्स / बोरॉन', 'Micronutrients', 'IPL Potash Essential Boron Micronutrient', '10.5% Boron for soil / 20.0% Solubor for foliar spray', 'Soil: 2-4 kg/acre. Foliar: 1g/L water at flower initiation to prevent flower dropping.', 'Avoid overdosing which causes boron toxicity.', 'Tomato, Pomegranate, Mustard, Cauliflower, Apple', 'https://images.unsplash.com/photo-1615485290382-441e4d049cb5?auto=format&fit=crop&w=360&q=75', '₹232.80', false, '1 kg Pack');
INSERT INTO fertilizers (name, hindi_name, category, type, composition, usage_instruction, precautions, suitable_crops, image_url, price_per_bag, subsidized, standard_pack_size) VALUES ('IPL Potash - Agricultural Gypsum (CaSO4.2H2O)', 'आईपीएल - कृषि जिप्सम', 'Soil Amendments', 'IPL Potash Calcium & Sulphur Soil Conditioner', '70-80% Calcium Sulphate (23% Ca + 18% S)', 'Reclamation of alkali soils: 200-500 kg/acre. Groundnut pegging: 100 kg/acre.', 'Broadcast uniformly and incorporate into top 10 cm soil.', 'Groundnut, Mustard, Sodic soils, Potato, Sugarcane', 'https://images.unsplash.com/photo-1567401893414-76b7b1e5a7a5?auto=format&fit=crop&w=360&q=75', '₹350.00', true, '50 kg Bag');
INSERT INTO fertilizers (name, hindi_name, category, type, composition, usage_instruction, precautions, suitable_crops, image_url, price_per_bag, subsidized, standard_pack_size) VALUES ('IPL Potash - Calcium Nitrate (15.5% N + 18.8% Ca)', 'आईपीएल - कैल्शियम नाइट्रेट', 'Secondary Nutrients', 'IPL Potash Water Soluble Plant Nutrient', '15.5% Nitrate Nitrogen + 18.8% Water Soluble Calcium', 'Drip fertigation @ 3-5 kg/acre or foliar spray @ 5g/L. Prevents blossom end rot in tomato.', 'Do not mix with sulphate or phosphate fertilizers in concentrated stock solution.', 'Tomato, Apple, Pomegranate, Potato, Capsicum', 'https://images.unsplash.com/photo-1567401893414-76b7b1e5a7a5?auto=format&fit=crop&w=360&q=75', '₹1,794.50', false, '25 kg Bag');
INSERT INTO fertilizers (name, hindi_name, category, type, composition, usage_instruction, precautions, suitable_crops, image_url, price_per_bag, subsidized, standard_pack_size) VALUES ('IPL Potash - Magnesium Sulphate (Epsom Salt 9.6% Mg + 12% S)', 'आईपीएल - मैग्नीशियम सल्फेट', 'Secondary Nutrients', 'IPL Potash Chlorophyll Booster', '9.6% Magnesium + 12.0% Sulphur', 'Soil application: 15-25 kg/acre. Foliar: 5g/L. Restores lush green color and photosynthesis.', 'Fast acting; highly water soluble.', 'Cotton, Sugarcane, Citrus, Banana, Tomato, Tea', 'https://images.unsplash.com/photo-1567401893414-76b7b1e5a7a5?auto=format&fit=crop&w=360&q=75', '₹727.50', false, '25 kg Bag');
INSERT INTO fertilizers (name, hindi_name, category, type, composition, usage_instruction, precautions, suitable_crops, image_url, price_per_bag, subsidized, standard_pack_size) VALUES ('IPL Potash - 100% Water Soluble NPK 19:19:19', 'आईपीएल - घुलनशील 19:19:19', 'Water Soluble & Foliar', 'IPL Potash Foliar & Fertigation Grade', '19% N, 19% P2O5, 19% K2O with balanced trace elements', 'Foliar spray @ 5g/L or fertigation @ 3-5 kg/acre during vegetative stage.', 'Completely soluble in water leaving no residue in drip nozzles.', 'Vegetables, Floriculture, Cotton, Fruits, Wheat', 'https://images.unsplash.com/photo-1592924357228-91a4daadcfea?auto=format&fit=crop&w=360&q=75', '₹174.60', false, '1 kg Pack');
INSERT INTO fertilizers (name, hindi_name, category, type, composition, usage_instruction, precautions, suitable_crops, image_url, price_per_bag, subsidized, standard_pack_size) VALUES ('IPL Potash - Mono Potassium Phosphate 0:52:34 (MKP)', 'आईपीएल - एमकेपी 0:52:34', 'Water Soluble & Foliar', 'IPL Potash Pre-flowering & Fruit Set Booster', '52.0% Available Phosphate + 34.0% Soluble Potash', 'Foliar spray @ 5g/L or drip @ 3kg/acre during bud initiation and grain filling.', 'Increases fruit size, sweetness (Brix), and disease resistance.', 'Grapes, Pomegranate, Tomato, Chilli, Wheat, Apple', 'https://images.unsplash.com/photo-1592924357228-91a4daadcfea?auto=format&fit=crop&w=360&q=75', '₹213.40', false, '1 kg Pack');
INSERT INTO fertilizers (name, hindi_name, category, type, composition, usage_instruction, precautions, suitable_crops, image_url, price_per_bag, subsidized, standard_pack_size) VALUES ('IPL Potash - Potassium Nitrate 13:0:45', 'आईपीएल - पोटेशियम नाइट्रेट 13:0:45', 'Water Soluble & Foliar', 'IPL Potash Fruit Maturity & Color Booster', '13.0% Nitrate Nitrogen + 45.0% Water Soluble Potash', 'Foliar spray @ 5-10g/L during fruit enlargement and ripening.', 'Improves fruit uniform ripening, shine, shelf life, and weight.', 'Pomegranate, Banana, Mango, Tomato, Potato, Onion', 'https://images.unsplash.com/photo-1615811361523-6bd03d7748e7?auto=format&fit=crop&w=360&q=75', '₹203.70', false, '1 kg Pack');
INSERT INTO fertilizers (name, hindi_name, category, type, composition, usage_instruction, precautions, suitable_crops, image_url, price_per_bag, subsidized, standard_pack_size) VALUES ('IPL Potash - Biofertilizer Consortia (NPK Liquid)', 'आईपीएल - तरल बायो एनपीके', 'Organic & Biofertilizers', 'IPL Potash Microbial Liquid Inoculant', 'Live strains of Azotobacter (Nitrogen fixing), Bacillus (PSB), and Frateuria (KMB) (1x10^8 CFU/ml)', 'Seed treatment: 10ml/kg; Soil drench or drip: 1 Liter/acre in 200L water.', 'Store in cool place out of direct sunlight. Do not mix with chemical bactericides.', 'All crops, organic farming, cereals, pulses, vegetables', 'https://images.unsplash.com/photo-1589923188900-85dae523342b?auto=format&fit=crop&w=360&q=75', '₹271.60', false, '1 Liter Bottle');
INSERT INTO fertilizers (name, hindi_name, category, type, composition, usage_instruction, precautions, suitable_crops, image_url, price_per_bag, subsidized, standard_pack_size) VALUES ('IPL Potash - Enriched Vermicompost (Organic Carbon 18%)', 'आईपीएल - वर्मीकम्पोस्ट (केंचुआ खाद)', 'Organic & Biofertilizers', 'IPL Potash 100% Organic Soil Enrichment', 'Organic Carbon 18-20%, Total N 1.8%, P 1.2%, K 1.5%, beneficial enzymes & worm castings', '1-2 tons per acre before last ploughing or 3-5 kg per fruit tree basin.', 'Eco-friendly; enhances soil water retention and beneficial soil microbiology.', 'All crops, organic farming, horticulture, greenhouse', 'https://images.unsplash.com/photo-1589923188900-85dae523342b?auto=format&fit=crop&w=360&q=75', '₹310.40', false, '40 kg Bag');
INSERT INTO fertilizers (name, hindi_name, category, type, composition, usage_instruction, precautions, suitable_crops, image_url, price_per_bag, subsidized, standard_pack_size) VALUES ('IPL Potash - Pure Cold-Pressed Neem Cake Powder', 'आईपीएल - नीम की खली (नीम केक)', 'Organic & Biofertilizers', 'IPL Potash Organic Manure & Nematicide', 'Azadirachtin content >1000 ppm, N 4.0%, P 1.0%, K 1.5%', 'Apply 100-150 kg/acre at soil preparation. Inhibits nitrification and controls soil nematodes.', 'Safe for earthworms and soil flora.', 'Vegetables, Potato, Banana, Spices, Cotton, Pomegranate', 'https://images.unsplash.com/photo-1589923188900-85dae523342b?auto=format&fit=crop&w=360&q=75', '₹824.50', false, '50 kg Bag');
INSERT INTO fertilizers (name, hindi_name, category, type, composition, usage_instruction, precautions, suitable_crops, image_url, price_per_bag, subsidized, standard_pack_size) VALUES ('IPL Potash - Liquid Humic Acid 12% + Fulvic Acid', 'आईपीएल - ह्यूमिक एसिड लिक्विड', 'Organic & Biofertilizers', 'IPL Potash Root Stimulant & Soil Conditioner', '12% Potassium Humate + Fulvic Acid + Amino Acids', 'Drenching or drip @ 1-2 Liters/acre; seed treatment @ 5ml/kg. Stimulates white feeder root growth.', 'Shake well before use. Compatible with NPK and micronutrients.', 'All crops during seedling and vegetative stages', 'https://images.unsplash.com/photo-1589923188900-85dae523342b?auto=format&fit=crop&w=360&q=75', '₹329.80', false, '1 Liter Bottle');
INSERT INTO fertilizers (name, hindi_name, category, type, composition, usage_instruction, precautions, suitable_crops, image_url, price_per_bag, subsidized, standard_pack_size) VALUES ('Nagarjuna - Neem Coated Urea (46% N)', 'नागार्जुन - नीम कोटेड यूरिया', 'Nitrogenous', 'Nagarjuna Nitrogen Fertilizer', '46.0% Total Nitrogen (Amide form) with 0.05% neem oil coating', 'Basal application at sowing + 2-3 split top dressings during vegetative growth.', 'Avoid overuse which causes lodging and pest susceptibility. Apply only on moist soil.', 'Wheat, Rice, Maize, Sugarcane, Cotton', 'https://images.unsplash.com/photo-1585314062340-f1a5a7c9328d?auto=format&fit=crop&w=360&q=75', '₹266.50', true, '45 kg Bag');
