INSERT INTO fertilizers (name, hindi_name, category, type, composition, usage_instruction, precautions, suitable_crops, image_url, price_per_bag, subsidized, standard_pack_size) VALUES ('Godrej Agrovet - Borax 10.5% / Disodium Octaborate 20%', 'गोदरेज एग्रोवेट - बोरेक्स / बोरॉन', 'Micronutrients', 'Godrej Agrovet Essential Boron Micronutrient', '10.5% Boron for soil / 20.0% Solubor for foliar spray', 'Soil: 2-4 kg/acre. Foliar: 1g/L water at flower initiation to prevent flower dropping.', 'Avoid overdosing which causes boron toxicity.', 'Tomato, Pomegranate, Mustard, Cauliflower, Apple', 'https://images.unsplash.com/photo-1615485290382-441e4d049cb5?auto=format&fit=crop&w=360&q=75', '₹228.00', false, '1 kg Pack');
