INSERT INTO fertilizers (name, hindi_name, category, type, composition, usage_instruction, precautions, suitable_crops, image_url, price_per_bag, subsidized, standard_pack_size) VALUES ('Godrej Agrovet - Magnesium Sulphate (Epsom Salt 9.6% Mg + 12% S)', 'गोदरेज एग्रोवेट - मैग्नीशियम सल्फेट', 'Secondary Nutrients', 'Godrej Agrovet Chlorophyll Booster', '9.6% Magnesium + 12.0% Sulphur', 'Soil application: 15-25 kg/acre. Foliar: 5g/L. Restores lush green color and photosynthesis.', 'Fast acting; highly water soluble.', 'Cotton, Sugarcane, Citrus, Banana, Tomato, Tea', 'https://images.unsplash.com/photo-1567401893414-76b7b1e5a7a5?auto=format&fit=crop&w=360&q=75', '₹712.50', false, '25 kg Bag');
