INSERT INTO fertilizers (name, hindi_name, category, type, composition, usage_instruction, precautions, suitable_crops, image_url, price_per_bag, subsidized, standard_pack_size) VALUES ('Godrej Agrovet - Mono Potassium Phosphate 0:52:34 (MKP)', 'गोदरेज एग्रोवेट - एमकेपी 0:52:34', 'Water Soluble & Foliar', 'Godrej Agrovet Pre-flowering & Fruit Set Booster', '52.0% Available Phosphate + 34.0% Soluble Potash', 'Foliar spray @ 5g/L or drip @ 3kg/acre during bud initiation and grain filling.', 'Increases fruit size, sweetness (Brix), and disease resistance.', 'Grapes, Pomegranate, Tomato, Chilli, Wheat, Apple', 'https://images.unsplash.com/photo-1592924357228-91a4daadcfea?auto=format&fit=crop&w=360&q=75', '₹209.00', false, '1 kg Pack');
