INSERT INTO fertilizers (name, hindi_name, category, type, composition, usage_instruction, precautions, suitable_crops, image_url, price_per_bag, subsidized, standard_pack_size) VALUES ('Godrej Agrovet - Biofertilizer Consortia (NPK Liquid)', 'गोदरेज एग्रोवेट - तरल बायो एनपीके', 'Organic & Biofertilizers', 'Godrej Agrovet Microbial Liquid Inoculant', 'Live strains of Azotobacter (Nitrogen fixing), Bacillus (PSB), and Frateuria (KMB) (1x10^8 CFU/ml)', 'Seed treatment: 10ml/kg; Soil drench or drip: 1 Liter/acre in 200L water.', 'Store in cool place out of direct sunlight. Do not mix with chemical bactericides.', 'All crops, organic farming, cereals, pulses, vegetables', 'https://images.unsplash.com/photo-1589923188900-85dae523342b?auto=format&fit=crop&w=360&q=75', '₹266.00', false, '1 Liter Bottle');
INSERT INTO fertilizers (name, hindi_name, category, type, composition, usage_instruction, precautions, suitable_crops, image_url, price_per_bag, subsidized, standard_pack_size) VALUES ('Godrej Agrovet - Enriched Vermicompost (Organic Carbon 18%)', 'गोदरेज एग्रोवेट - वर्मीकम्पोस्ट (केंचुआ खाद)', 'Organic & Biofertilizers', 'Godrej Agrovet 100% Organic Soil Enrichment', 'Organic Carbon 18-20%, Total N 1.8%, P 1.2%, K 1.5%, beneficial enzymes & worm castings', '1-2 tons per acre before last ploughing or 3-5 kg per fruit tree basin.', 'Eco-friendly; enhances soil water retention and beneficial soil microbiology.', 'All crops, organic farming, horticulture, greenhouse', 'https://images.unsplash.com/photo-1589923188900-85dae523342b?auto=format&fit=crop&w=360&q=75', '₹304.00', false, '40 kg Bag');
