INSERT INTO fertilizers (name, hindi_name, category, type, composition, usage_instruction, precautions, suitable_crops, image_url, price_per_bag, subsidized, standard_pack_size) VALUES ('UPL Fertis - Liquid Humic Acid 12% + Fulvic Acid', 'यूपीएल - ह्यूमिक एसिड लिक्विड', 'Organic & Biofertilizers', 'UPL Fertis Root Stimulant & Soil Conditioner', '12% Potassium Humate + Fulvic Acid + Amino Acids', 'Drenching or drip @ 1-2 Liters/acre; seed treatment @ 5ml/kg. Stimulates white feeder root growth.', 'Shake well before use. Compatible with NPK and micronutrients.', 'All crops during seedling and vegetative stages', 'https://images.unsplash.com/photo-1589923188900-85dae523342b?auto=format&fit=crop&w=360&q=75', '₹336.60', false, '1 Liter Bottle');
INSERT INTO fertilizers (name, hindi_name, category, type, composition, usage_instruction, precautions, suitable_crops, image_url, price_per_bag, subsidized, standard_pack_size) VALUES ('Chambal Fertilisers (Uttam) - Neem Coated Urea (46% N)', 'चंबल फर्टिलाइजर्स - नीम कोटेड यूरिया', 'Nitrogenous', 'Chambal Fertilisers (Uttam) Nitrogen Fertilizer', '46.0% Total Nitrogen (Amide form) with 0.05% neem oil coating', 'Basal application at sowing + 2-3 split top dressings during vegetative growth.', 'Avoid overuse which causes lodging and pest susceptibility. Apply only on moist soil.', 'Wheat, Rice, Maize, Sugarcane, Cotton', 'https://images.unsplash.com/photo-1585314062340-f1a5a7c9328d?auto=format&fit=crop&w=360&q=75', '₹266.50', true, '45 kg Bag');
INSERT INTO fertilizers (name, hindi_name, category, type, composition, usage_instruction, precautions, suitable_crops, image_url, price_per_bag, subsidized, standard_pack_size) VALUES ('Chambal Fertilisers (Uttam) - DAP (Di-Ammonium Phosphate 18:46:0)', 'चंबल फर्टिलाइजर्स - डीएपी', 'Phosphatic', 'Chambal Fertilisers (Uttam) Phosphorus & Nitrogen Complex', '18.0% Ammoniacal Nitrogen + 46.0% Available Phosphate (P2O5)', 'Basal dose at sowing near root zone for vigorous root growth.', 'Store in dry place. Do not mix with quicklime or calcium nitrate.', 'All crops: Wheat, Paddy, Potato, Mustard, Pulses', 'https://images.unsplash.com/photo-1628352081506-83c43123ed6d?auto=format&fit=crop&w=360&q=75', '₹1,350.00', true, '50 kg Bag');
INSERT INTO fertilizers (name, hindi_name, category, type, composition, usage_instruction, precautions, suitable_crops, image_url, price_per_bag, subsidized, standard_pack_size) VALUES ('Chambal Fertilisers (Uttam) - MOP (Muriate of Potash 0:0:60)', 'चंबल फर्टिलाइजर्स - एमओपी (पोटाश)', 'Potassic', 'Chambal Fertilisers (Uttam) Potassium Fertilizer', '60.0% Water Soluble Potash (K2O as KCl)', 'Basal or split application for heavy feeding crops; boosts grain weight and drought resistance.', 'Avoid for chloride-sensitive crops like tobacco, grapes, potato starch.', 'Paddy, Sugarcane, Wheat, Maize, Cotton, Banana', 'https://images.unsplash.com/photo-1615811361523-6bd03d7748e7?auto=format&fit=crop&w=360&q=75', '₹1,650.00', true, '50 kg Bag');
INSERT INTO fertilizers (name, hindi_name, category, type, composition, usage_instruction, precautions, suitable_crops, image_url, price_per_bag, subsidized, standard_pack_size) VALUES ('Chambal Fertilisers (Uttam) - NPK 10:26:26 Complex', 'चंबल फर्टिलाइजर्स - एनपीके 10:26:26', 'Complex NPK', 'Chambal Fertilisers (Uttam) Complete Balanced Fertilizer', '10.0% N, 26.0% P2O5, 26.0% K2O', 'Ideal basal fertilizer for heavy feeding crops and root/tuber development.', 'Uniform granule distribution ensures balanced nutrition.', 'Cotton, Sugarcane, Potato, Pulses, Oilseeds', 'https://images.unsplash.com/photo-1592924357228-91a4daadcfea?auto=format&fit=crop&w=360&q=75', '₹1,470.00', true, '50 kg Bag');
INSERT INTO fertilizers (name, hindi_name, category, type, composition, usage_instruction, precautions, suitable_crops, image_url, price_per_bag, subsidized, standard_pack_size) VALUES ('Chambal Fertilisers (Uttam) - NPK 12:32:16 Complex', 'चंबल फर्टिलाइजर्स - एनपीके 12:32:16', 'Complex NPK', 'Chambal Fertilisers (Uttam) High Phosphate Complex', '12.0% N, 32.0% P2O5, 16.0% K2O', 'High phosphorus booster for root proliferation and early plant establishment.', 'Incorporate 3-5 cm below seed depth.', 'Wheat, Mustard, Soybean, Paddy, Groundnut', 'https://images.unsplash.com/photo-1592924357228-91a4daadcfea?auto=format&fit=crop&w=360&q=75', '₹1,470.00', true, '50 kg Bag');
INSERT INTO fertilizers (name, hindi_name, category, type, composition, usage_instruction, precautions, suitable_crops, image_url, price_per_bag, subsidized, standard_pack_size) VALUES ('Chambal Fertilisers (Uttam) - NPK 20:20:0:13 Ammonium Phosphate Sulphate', 'चंबल फर्टिलाइजर्स - एनपीके 20:20:0:13 (सल्फर युक्त)', 'Complex NPK', 'Chambal Fertilisers (Uttam) Nitrogen, Phosphate & Sulphur Complex', '20.0% N, 20.0% P2O5, 13.0% Sulphur', 'Excellent for oilseeds and pulses where sulphur is critical for oil and protein synthesis.', 'Store away from direct moisture.', 'Mustard, Soybean, Groundnut, Sunflower, Pulses', 'https://images.unsplash.com/photo-1592924357228-91a4daadcfea?auto=format&fit=crop&w=360&q=75', '₹1,320.00', true, '50 kg Bag');
INSERT INTO fertilizers (name, hindi_name, category, type, composition, usage_instruction, precautions, suitable_crops, image_url, price_per_bag, subsidized, standard_pack_size) VALUES ('Chambal Fertilisers (Uttam) - Single Super Phosphate (SSP 16% P2O5 + 11% S)', 'चंबल फर्टिलाइजर्स - एसएसपी (सुपर फॉस्फेट)', 'Phosphatic', 'Chambal Fertilisers (Uttam) Phosphorus, Calcium & Sulphur Fertilizer', '16.0% Water Soluble Phosphate + 11.0% Sulphur + 19.0% Calcium', 'Basal application at field preparation or sowing; soil conditioner for sodic soils.', 'Can be mixed with Urea at time of application; do not store mixed.', 'Groundnut, Mustard, Soybean, Pulses, Potato', 'https://images.unsplash.com/photo-1500937386664-56d1dfef3854?auto=format&fit=crop&w=360&q=75', '₹520.00', true, '50 kg Bag');
INSERT INTO fertilizers (name, hindi_name, category, type, composition, usage_instruction, precautions, suitable_crops, image_url, price_per_bag, subsidized, standard_pack_size) VALUES ('Chambal Fertilisers (Uttam) - Zinc Sulphate 33% Monohydrate', 'चंबल फर्टिलाइजर्स - जिंक सल्फेट 33%', 'Micronutrients', 'Chambal Fertilisers (Uttam) Essential Zinc & Sulphur Micronutrient', '33.0% Zinc (Zn) + 15.0% Sulphur (S)', 'Soil application 5-7.5 kg/acre or foliar spray 0.5% with lime. Prevents Khaira disease in paddy.', 'Never mix directly with DAP or SSP in water tank.', 'Paddy, Wheat, Maize, Citrus, Cotton, Sugarcane', 'https://images.unsplash.com/photo-1585314062340-f1a5a7c9328d?auto=format&fit=crop&w=360&q=75', '₹450.00', false, '5 kg Pack');
INSERT INTO fertilizers (name, hindi_name, category, type, composition, usage_instruction, precautions, suitable_crops, image_url, price_per_bag, subsidized, standard_pack_size) VALUES ('Chambal Fertilisers (Uttam) - Chelated Zinc EDTA 12%', 'चंबल फर्टिलाइजर्स - चिलेटेड जिंक 12%', 'Micronutrients', 'Chambal Fertilisers (Uttam) 100% Water Soluble Chelate', '12.0% Zinc in EDTA chelated form', 'Foliar spray @ 1g/L water during active growth; rapid absorption through leaves.', 'Compatible with most common agricultural sprays.', 'Paddy, Citrus, Cotton, Apple, Tomato, Vegetables', 'https://images.unsplash.com/photo-1615485290382-441e4d049cb5?auto=format&fit=crop&w=360&q=75', '₹380.00', false, '1 kg Pouch');
INSERT INTO fertilizers (name, hindi_name, category, type, composition, usage_instruction, precautions, suitable_crops, image_url, price_per_bag, subsidized, standard_pack_size) VALUES ('Chambal Fertilisers (Uttam) - Borax 10.5% / Disodium Octaborate 20%', 'चंबल फर्टिलाइजर्स - बोरेक्स / बोरॉन', 'Micronutrients', 'Chambal Fertilisers (Uttam) Essential Boron Micronutrient', '10.5% Boron for soil / 20.0% Solubor for foliar spray', 'Soil: 2-4 kg/acre. Foliar: 1g/L water at flower initiation to prevent flower dropping.', 'Avoid overdosing which causes boron toxicity.', 'Tomato, Pomegranate, Mustard, Cauliflower, Apple', 'https://images.unsplash.com/photo-1615485290382-441e4d049cb5?auto=format&fit=crop&w=360&q=75', '₹240.00', false, '1 kg Pack');
INSERT INTO fertilizers (name, hindi_name, category, type, composition, usage_instruction, precautions, suitable_crops, image_url, price_per_bag, subsidized, standard_pack_size) VALUES ('Chambal Fertilisers (Uttam) - Agricultural Gypsum (CaSO4.2H2O)', 'चंबल फर्टिलाइजर्स - कृषि जिप्सम', 'Soil Amendments', 'Chambal Fertilisers (Uttam) Calcium & Sulphur Soil Conditioner', '70-80% Calcium Sulphate (23% Ca + 18% S)', 'Reclamation of alkali soils: 200-500 kg/acre. Groundnut pegging: 100 kg/acre.', 'Broadcast uniformly and incorporate into top 10 cm soil.', 'Groundnut, Mustard, Sodic soils, Potato, Sugarcane', 'https://images.unsplash.com/photo-1567401893414-76b7b1e5a7a5?auto=format&fit=crop&w=360&q=75', '₹350.00', true, '50 kg Bag');
INSERT INTO fertilizers (name, hindi_name, category, type, composition, usage_instruction, precautions, suitable_crops, image_url, price_per_bag, subsidized, standard_pack_size) VALUES ('Chambal Fertilisers (Uttam) - Calcium Nitrate (15.5% N + 18.8% Ca)', 'चंबल फर्टिलाइजर्स - कैल्शियम नाइट्रेट', 'Secondary Nutrients', 'Chambal Fertilisers (Uttam) Water Soluble Plant Nutrient', '15.5% Nitrate Nitrogen + 18.8% Water Soluble Calcium', 'Drip fertigation @ 3-5 kg/acre or foliar spray @ 5g/L. Prevents blossom end rot in tomato.', 'Do not mix with sulphate or phosphate fertilizers in concentrated stock solution.', 'Tomato, Apple, Pomegranate, Potato, Capsicum', 'https://images.unsplash.com/photo-1567401893414-76b7b1e5a7a5?auto=format&fit=crop&w=360&q=75', '₹1,850.00', false, '25 kg Bag');
INSERT INTO fertilizers (name, hindi_name, category, type, composition, usage_instruction, precautions, suitable_crops, image_url, price_per_bag, subsidized, standard_pack_size) VALUES ('Chambal Fertilisers (Uttam) - Magnesium Sulphate (Epsom Salt 9.6% Mg + 12% S)', 'चंबल फर्टिलाइजर्स - मैग्नीशियम सल्फेट', 'Secondary Nutrients', 'Chambal Fertilisers (Uttam) Chlorophyll Booster', '9.6% Magnesium + 12.0% Sulphur', 'Soil application: 15-25 kg/acre. Foliar: 5g/L. Restores lush green color and photosynthesis.', 'Fast acting; highly water soluble.', 'Cotton, Sugarcane, Citrus, Banana, Tomato, Tea', 'https://images.unsplash.com/photo-1567401893414-76b7b1e5a7a5?auto=format&fit=crop&w=360&q=75', '₹750.00', false, '25 kg Bag');
INSERT INTO fertilizers (name, hindi_name, category, type, composition, usage_instruction, precautions, suitable_crops, image_url, price_per_bag, subsidized, standard_pack_size) VALUES ('Chambal Fertilisers (Uttam) - 100% Water Soluble NPK 19:19:19', 'चंबल फर्टिलाइजर्स - घुलनशील 19:19:19', 'Water Soluble & Foliar', 'Chambal Fertilisers (Uttam) Foliar & Fertigation Grade', '19% N, 19% P2O5, 19% K2O with balanced trace elements', 'Foliar spray @ 5g/L or fertigation @ 3-5 kg/acre during vegetative stage.', 'Completely soluble in water leaving no residue in drip nozzles.', 'Vegetables, Floriculture, Cotton, Fruits, Wheat', 'https://images.unsplash.com/photo-1592924357228-91a4daadcfea?auto=format&fit=crop&w=360&q=75', '₹180.00', false, '1 kg Pack');
INSERT INTO fertilizers (name, hindi_name, category, type, composition, usage_instruction, precautions, suitable_crops, image_url, price_per_bag, subsidized, standard_pack_size) VALUES ('Chambal Fertilisers (Uttam) - Mono Potassium Phosphate 0:52:34 (MKP)', 'चंबल फर्टिलाइजर्स - एमकेपी 0:52:34', 'Water Soluble & Foliar', 'Chambal Fertilisers (Uttam) Pre-flowering & Fruit Set Booster', '52.0% Available Phosphate + 34.0% Soluble Potash', 'Foliar spray @ 5g/L or drip @ 3kg/acre during bud initiation and grain filling.', 'Increases fruit size, sweetness (Brix), and disease resistance.', 'Grapes, Pomegranate, Tomato, Chilli, Wheat, Apple', 'https://images.unsplash.com/photo-1592924357228-91a4daadcfea?auto=format&fit=crop&w=360&q=75', '₹220.00', false, '1 kg Pack');
