INSERT INTO fertilizers (name, hindi_name, category, type, composition, usage_instruction, precautions, suitable_crops, image_url, price_per_bag, subsidized, standard_pack_size) VALUES ('KRIBHCO Shyam - Mono Potassium Phosphate 0:52:34 (MKP)', 'कृभको श्याम - एमकेपी 0:52:34', 'Water Soluble & Foliar', 'KRIBHCO Shyam Pre-flowering & Fruit Set Booster', '52.0% Available Phosphate + 34.0% Soluble Potash', 'Foliar spray @ 5g/L or drip @ 3kg/acre during bud initiation and grain filling.', 'Increases fruit size, sweetness (Brix), and disease resistance.', 'Grapes, Pomegranate, Tomato, Chilli, Wheat, Apple', 'https://images.unsplash.com/photo-1592924357228-91a4daadcfea?auto=format&fit=crop&w=360&q=75', '₹224.40', false, '1 kg Pack');
INSERT INTO fertilizers (name, hindi_name, category, type, composition, usage_instruction, precautions, suitable_crops, image_url, price_per_bag, subsidized, standard_pack_size) VALUES ('KRIBHCO Shyam - Potassium Nitrate 13:0:45', 'कृभको श्याम - पोटेशियम नाइट्रेट 13:0:45', 'Water Soluble & Foliar', 'KRIBHCO Shyam Fruit Maturity & Color Booster', '13.0% Nitrate Nitrogen + 45.0% Water Soluble Potash', 'Foliar spray @ 5-10g/L during fruit enlargement and ripening.', 'Improves fruit uniform ripening, shine, shelf life, and weight.', 'Pomegranate, Banana, Mango, Tomato, Potato, Onion', 'https://images.unsplash.com/photo-1615811361523-6bd03d7748e7?auto=format&fit=crop&w=360&q=75', '₹214.20', false, '1 kg Pack');
INSERT INTO fertilizers (name, hindi_name, category, type, composition, usage_instruction, precautions, suitable_crops, image_url, price_per_bag, subsidized, standard_pack_size) VALUES ('KRIBHCO Shyam - Biofertilizer Consortia (NPK Liquid)', 'कृभको श्याम - तरल बायो एनपीके', 'Organic & Biofertilizers', 'KRIBHCO Shyam Microbial Liquid Inoculant', 'Live strains of Azotobacter (Nitrogen fixing), Bacillus (PSB), and Frateuria (KMB) (1x10^8 CFU/ml)', 'Seed treatment: 10ml/kg; Soil drench or drip: 1 Liter/acre in 200L water.', 'Store in cool place out of direct sunlight. Do not mix with chemical bactericides.', 'All crops, organic farming, cereals, pulses, vegetables', 'https://images.unsplash.com/photo-1589923188900-85dae523342b?auto=format&fit=crop&w=360&q=75', '₹285.60', false, '1 Liter Bottle');
INSERT INTO fertilizers (name, hindi_name, category, type, composition, usage_instruction, precautions, suitable_crops, image_url, price_per_bag, subsidized, standard_pack_size) VALUES ('KRIBHCO Shyam - Enriched Vermicompost (Organic Carbon 18%)', 'कृभको श्याम - वर्मीकम्पोस्ट (केंचुआ खाद)', 'Organic & Biofertilizers', 'KRIBHCO Shyam 100% Organic Soil Enrichment', 'Organic Carbon 18-20%, Total N 1.8%, P 1.2%, K 1.5%, beneficial enzymes & worm castings', '1-2 tons per acre before last ploughing or 3-5 kg per fruit tree basin.', 'Eco-friendly; enhances soil water retention and beneficial soil microbiology.', 'All crops, organic farming, horticulture, greenhouse', 'https://images.unsplash.com/photo-1589923188900-85dae523342b?auto=format&fit=crop&w=360&q=75', '₹326.40', false, '40 kg Bag');
INSERT INTO fertilizers (name, hindi_name, category, type, composition, usage_instruction, precautions, suitable_crops, image_url, price_per_bag, subsidized, standard_pack_size) VALUES ('KRIBHCO Shyam - Pure Cold-Pressed Neem Cake Powder', 'कृभको श्याम - नीम की खली (नीम केक)', 'Organic & Biofertilizers', 'KRIBHCO Shyam Organic Manure & Nematicide', 'Azadirachtin content >1000 ppm, N 4.0%, P 1.0%, K 1.5%', 'Apply 100-150 kg/acre at soil preparation. Inhibits nitrification and controls soil nematodes.', 'Safe for earthworms and soil flora.', 'Vegetables, Potato, Banana, Spices, Cotton, Pomegranate', 'https://images.unsplash.com/photo-1589923188900-85dae523342b?auto=format&fit=crop&w=360&q=75', '₹867.00', false, '50 kg Bag');
INSERT INTO fertilizers (name, hindi_name, category, type, composition, usage_instruction, precautions, suitable_crops, image_url, price_per_bag, subsidized, standard_pack_size) VALUES ('KRIBHCO Shyam - Liquid Humic Acid 12% + Fulvic Acid', 'कृभको श्याम - ह्यूमिक एसिड लिक्विड', 'Organic & Biofertilizers', 'KRIBHCO Shyam Root Stimulant & Soil Conditioner', '12% Potassium Humate + Fulvic Acid + Amino Acids', 'Drenching or drip @ 1-2 Liters/acre; seed treatment @ 5ml/kg. Stimulates white feeder root growth.', 'Shake well before use. Compatible with NPK and micronutrients.', 'All crops during seedling and vegetative stages', 'https://images.unsplash.com/photo-1589923188900-85dae523342b?auto=format&fit=crop&w=360&q=75', '₹346.80', false, '1 Liter Bottle');
INSERT INTO fertilizers (name, hindi_name, category, type, composition, usage_instruction, precautions, suitable_crops, image_url, price_per_bag, subsidized, standard_pack_size) VALUES ('Paradeep Phosphates - Neem Coated Urea (46% N)', 'पारादीप फॉस्फेट्स - नीम कोटेड यूरिया', 'Nitrogenous', 'Paradeep Phosphates Nitrogen Fertilizer', '46.0% Total Nitrogen (Amide form) with 0.05% neem oil coating', 'Basal application at sowing + 2-3 split top dressings during vegetative growth.', 'Avoid overuse which causes lodging and pest susceptibility. Apply only on moist soil.', 'Wheat, Rice, Maize, Sugarcane, Cotton', 'https://images.unsplash.com/photo-1585314062340-f1a5a7c9328d?auto=format&fit=crop&w=360&q=75', '₹266.50', true, '45 kg Bag');
