INSERT INTO fertilizers (name, hindi_name, category, type, composition, usage_instruction, precautions, suitable_crops, image_url, price_per_bag, subsidized, standard_pack_size) VALUES ('Rashtriya Chemicals - Zinc Sulphate 33% Monohydrate', 'आरसीएफ - जिंक सल्फेट 33%', 'Micronutrients', 'Rashtriya Chemicals Essential Zinc & Sulphur Micronutrient', '33.0% Zinc (Zn) + 15.0% Sulphur (S)', 'Soil application 5-7.5 kg/acre or foliar spray 0.5% with lime. Prevents Khaira disease in paddy.', 'Never mix directly with DAP or SSP in water tank.', 'Paddy, Wheat, Maize, Citrus, Cotton, Sugarcane', 'https://images.unsplash.com/photo-1585314062340-f1a5a7c9328d?auto=format&fit=crop&w=360&q=75', '₹459.00', false, '5 kg Pack');
